/*
 * A376425  Numbers whose adjacent digits differ by at most 1 modulo 10.
 * https://oeis.org/A376425
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   A376425 – numbers whose adjacent digits differ by at most 1
 *            modulo 10. The values are generated by dynamic programming:
 *            ways[k][d] gives the count of k‑digit admissible numbers whose
 *            first digit is d. The nth term is constructed digit by digit
 *            using these counts
 * Range:     u8 n <= 55, u16 n <= 775, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

#define MAX_LEN 10            /* enough for n ≤ 10000 (length ≤ 7) */

static idx_t ways[MAX_LEN + 1][10];
static idx_t totals[MAX_LEN + 1];
static int initialized = 0;

seq_t a(idx_t n)
{
    /* The first ten single‑digit terms. */
    if (n <= 10u)
        return (seq_t)(n - 1);

    /* Initialise the DP tables once. */
    if (!initialized) {
        /* Length‑1 sequences: one for each digit. */
        for (int d = 0; d < 10; ++d)
            ways[1][d] = 1;

        /* DP: ways[k][d] = ∑ ways[k-1][nb] over all neighbours nb of d. */
        for (int k = 2; k <= MAX_LEN; ++k) {
            for (int d = 0; d < 10; ++d) {
                idx_t cnt = 0;
                /* neighbours: d-1, d, d+1 (mod 10) */
                int nb1 = (d + 9) % 10;   /* d-1 */
                int nb2 = d;              /* d   */
                int nb3 = (d + 1) % 10;   /* d+1 */
                cnt += ways[k - 1][nb1];
                cnt += ways[k - 1][nb2];
                cnt += ways[k - 1][nb3];
                ways[k][d] = cnt;
            }
        }

        /* Count how many admissible numbers have a given length. */
        totals[1] = 10;   /* 0–9 */
        for (int k = 2; k <= MAX_LEN; ++k) {
            idx_t sum = 0;
            for (int d = 1; d < 10; ++d)   /* leading digit ≠ 0 */
                sum += ways[k][d];
            totals[k] = sum;
        }

        initialized = 1;
    }

    /* Work with 1‑based index relative to the first multi‑digit term. */
    idx_t rem = n - 10;            /* position among 2‑digit and longer numbers */

    /* Find the length of the desired number. */
    idx_t cumulative = 0;
    int len = 2;
    while (rem > cumulative + totals[len]) {
        cumulative += totals[len];
        ++len;
        /* len never exceeds MAX_LEN for the required n. */
    }

    /* Position within the block of numbers of this length (1‑based). */
    idx_t offset = rem - cumulative;

    /* Construct the number digit by digit. */
    seq_t result = 0;
    idx_t pos_val = offset;        /* still 1‑based */
    int prev = -1;                 /* no previous digit at start */

    for (int pos = 1; pos <= len; ++pos) {
        int remaining = len - pos + 1;   /* positions left including this one */

        if (pos == 1) { /* choose leading digit (cannot be 0) */
            for (int d = 1; d < 10; ++d) {
                idx_t cnt = ways[remaining][d];
                if (pos_val > cnt)
                    pos_val -= cnt;
                else {
                    result = result * 10 + (seq_t)d;
                    prev = d;
                    break;
                }
            }
        } else { /* choose a neighbour of the previous digit */
            int neigh[3];
            int neigh_cnt;
            if (prev == 0) {
                neigh[0] = 0; neigh[1] = 1; neigh[2] = 9;
                neigh_cnt = 3;
            } else if (prev == 9) {
                neigh[0] = 0; neigh[1] = 8; neigh[2] = 9;
                neigh_cnt = 3;
            } else {
                neigh[0] = prev - 1; neigh[1] = prev; neigh[2] = prev + 1;
                neigh_cnt = 3;
            }
            for (int i = 0; i < neigh_cnt; ++i) {
                int d = neigh[i];
                idx_t cnt = ways[remaining][d];
                if (pos_val > cnt)
                    pos_val -= cnt;
                else {
                    result = result * 10 + (seq_t)d;
                    prev = d;
                    break;
                }
            }
        }
    }

    return result;
}
